import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> teks = new ArrayList<>();
        List<Integer> angka = new ArrayList<>();

        System.out.println(teks.getClass() == angka.getClass());
        System.out.println(teks.getClass().getSimpleName());

        Kotak<String> k1 = new Kotak<>("halo");
        Kotak<Integer> k2 = new Kotak<>(5);
        System.out.println(k1.getClass() == k2.getClass());
        System.out.println(k1.ambil() + " " + k2.ambil());

        Object o = angka;
        System.out.println(o instanceof List<?>);
    }
}

class Kotak<T> {
    private T isi;

    Kotak(T isi) {
        this.isi = isi;
    }

    T ambil() {
        return isi;
    }
}

