import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        Rak<String> rakTeks = new Rak<>();
        rakTeks.tambah("buku");
        rakTeks.tambah("pensil");
        Rak<Integer> rakAngka = new Rak<>();
        System.out.println(rakTeks.ambil(0));
        System.out.println(rakTeks.jumlah());
        System.out.println(rakTeks.getClass() == rakAngka.getClass());
    }
}

class Rak<T> {
    private List<T> isi = new ArrayList<>();

    void tambah(T x) {
        isi.add(x);
    }

    T ambil(int i) {
        return isi.get(i);
    }

    int jumlah() {
        return isi.size();
    }
}

